public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * Stages one NPSP Data Import record per gift and processes them synchronously
     * through NPSP's BDI (Data Importer) Apex API, so NPSP's contact matching,
     * household creation and donation processing rules apply. Each staged
     * npsp__DataImport__c record remains in the org as an audit trail.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Build one Data Import staging record per gift, keeping input order.
        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c(
                npsp__Contact1_Firstname__c      = gift.firstName,
                npsp__Contact1_Lastname__c       = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c         = gift.amount,
                npsp__Donation_Date__c           = gift.giftDate,
                npsp__Donation_Donor__c          = 'Contact1'
            );
            dataImports.add(di);
        }

        // Persist the staging records first so they remain as an audit trail.
        insert dataImports;

        // Process the records synchronously, in this same transaction, using the
        // org's Data Import settings. isDryRun = false so NPSP actually imports.
        // This overload loads the org's Data Import settings internally.
        npsp.BDI_DataImport_API.processDataImportRecords(dataImports, false);

        // Re-query the processed records to read back NPSP's results in input order.
        Set<Id> diIds = new Set<Id>();
        for (npsp__DataImport__c di : dataImports) {
            diIds.add(di.Id);
        }

        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>(
            [
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :diIds
            ]
        );

        // Build one ImportResult per gift, preserving input order.
        for (npsp__DataImport__c staged : dataImports) {
            npsp__DataImport__c processed = processedById.get(staged.Id);

            ImportResult result = new ImportResult();

            if (processed == null) {
                result.success = false;
                result.errorMessage = 'Data Import record could not be retrieved after processing.';
                results.add(result);
                continue;
            }

            Boolean imported =
                processed.npsp__Status__c == 'Imported';

            result.success = imported;
            result.contactId = processed.npsp__Contact1Imported__c;
            result.opportunityId = processed.npsp__DonationImported__c;

            if (!imported) {
                result.errorMessage = processed.npsp__FailureInformation__c;
            }

            results.add(result);
        }

        return results;
    }
}
```

