public with sharing class HouseholdService {

    /**
     * Creates a single NPSP Household account and attaches all given contacts to it.
     * The first contact becomes the household's primary contact.
     *
     * @param members New contacts (no Id, no AccountId) to place in one household.
     * @return The Id of the newly created Household account.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        // Look up the Household Account record type Id dynamically (no hard-coded Ids).
        Id householdRecordTypeId = Schema.SObjectType.Account
            .getRecordTypeInfosByDeveloperName()
            .get('HH_Account')
            .getRecordTypeId();

        // Create ONE real NPSP Household account up front with the HH_Account record type
        // so NPSP treats it as a household (naming + greetings). Account.Name is a required
        // field, so we provide a temporary placeholder; NPSP's household naming overwrites
        // it with the real automatic household name once members are linked.
        Account household = new Account(
            Name = 'NPSP Household',
            RecordTypeId = householdRecordTypeId
        );
        insert household;

        // Point every contact at the pre-created household. Because the contacts already
        // have an AccountId, NPSP will NOT auto-create extra households for them.
        for (Contact c : members) {
            c.AccountId = household.Id;
        }
        insert members;

        // Set the first contact as the household's primary contact. Updating the account
        // triggers NPSP's household naming/greeting logic over the linked members and
        // replaces the placeholder Name with the generated household name.
        household.npe01__One2OneContact__c = members[0].Id;
        update household;

        return household.Id;
    }
}
