public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>(triggerOld);
        List<Task> tasksToInsert = new List<Task>();

        for (Opportunity newOpp : triggerNew) {
            // Only act the first time this record is seen in the after-update context
            // for this transaction. The RoundAmount action re-updates the same records,
            // which re-fires this action; on that second pass the counter is > 1, so we
            // skip it and avoid creating a duplicate task per opportunity.
            Integer timesSeen = TriggerBase.idToNumberOfTimesSeenAfterUpdate.get(newOpp.Id);
            if (timesSeen != null && timesSeen > 1) {
                continue;
            }

            Opportunity oldOpp = oldById.get(newOpp.Id);
            if (oldOpp != null && newOpp.Amount != oldOpp.Amount) {
                tasksToInsert.add(
                    new Task(
                        Subject = 'Amount changed',
                        WhatId = newOpp.Id,
                        Status = 'Completed'
                    )
                );
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
