/**
 * Singleton that performs the shared parent-Account query for Contact trigger actions.
 *
 * The inner Service class is registered as the first before-insert trigger action
 * (Order 1). It reloads accountsById on every trigger execution, because later DML
 * in the same transaction can involve other accounts.
 *
 * Later actions call TA_Contact_Queries.getInstance().accountsById to read the parent
 * accounts without issuing their own queries, giving exactly one Account query per
 * trigger execution shared by all actions.
 */
public inherited sharing class TA_Contact_Queries {
    private static TA_Contact_Queries instance;

    public Map<Id, Account> accountsById { get; private set; }

    private TA_Contact_Queries() {
        this.accountsById = new Map<Id, Account>();
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Loads (or reloads) the parent accounts for the supplied contacts into accountsById.
     * Runs once per trigger execution via the Service action.
     */
    private void loadAccounts(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact con : contacts) {
            if (con.AccountId != null) {
                accountIds.add(con.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            this.accountsById = new Map<Id, Account>();
            return;
        }

        this.accountsById = new Map<Id, Account>(
            [
                SELECT
                    Id,
                    BillingStreet,
                    BillingCity,
                    BillingPostalCode,
                    BillingCountry,
                    AccountSource
                FROM Account
                WHERE Id IN :accountIds
            ]
        );
    }

    /**
     * Trigger action that loads the shared Account map. Registered first (Order 1) so
     * that subsequent before-insert actions can rely on accountsById being populated.
     */
    public inherited sharing class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            TA_Contact_Queries.getInstance().loadAccounts((List<Contact>) triggerNew);
        }
    }
}
